import subprocess, os, tempfile, base64
tmpdir=tempfile.mkdtemp(dir="/tmp")
def r(args):
    p=subprocess.run(["/workspace/executable"]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=tmpdir)
    return p.returncode, p.stdout, p.stderr

def varint_q11_comment(C):
    # 11 + (C-1)*32
    return 11 + (C-1)*32

def varint_q11_content_no_comment(L):
    # (L-1)*4
    return (L-1)*4 if L>=1 else 0

def varint_q11_content_with_comment(L):
    # (L-1)*8
    return (L-1)*8 if L>=1 else 0

def make_file_no_comment_q11(content):
    L=len(content)
    if L==0:
        return bytes.fromhex("a101")
    varint = varint_q11_content_no_comment(L)
    # file = 21 + varint (2 bytes LE) + 04 + content +03
    return bytes([0x21]) + varint.to_bytes(2,'little') + bytes([0x04]) + content + bytes([0x03])

def make_file_comment_q11(content, comment):
    C=len(comment)
    L=len(content)
    if L==0:
        varint_c = varint_q11_comment(C)
        return bytes([0x21]) + varint_c.to_bytes(2,'little') + comment + bytes([0x03])
    else:
        varint_c = varint_q11_comment(C)
        varint_content = varint_q11_content_with_comment(L)
        return bytes([0x21]) + varint_c.to_bytes(2,'little') + comment + varint_content.to_bytes(2,'little') + bytes([0x08]) + content + bytes([0x03])

# Test our manual files vs original exe decompression

for content in [b"",b"a",b"ab",b"abc",b"hello",b"hello world"]:
    for comment in [None, b"hi", b"hello"]:
        if comment is None:
            data = make_file_no_comment_q11(content)
        else:
            data = make_file_comment_q11(content, comment)
        open(os.path.join(tmpdir,"test.br"),"wb").write(data)
        rc,out,err = r(["-d","-c","test.br"])
        # try decompress with original exe
        print(f"content {content!r} comment {comment} file {data.hex()} => rc {rc} out {out[:20]} err {err.decode()[:100]}")

