            // The API: BrotliEncoderCompressStream(state, op, avail_in, next_in, avail_out, next_out, total_out)
            // total_out is updated to total bytes output so far.
            // So we need to track.

            // For simplicity, loop
            if(avail_in==0) break;
        } else {
            // Finish
            size_t avail_out2 = out_capacity - total_out;
            uint8_t* nxt_out2 = out_buf + total_out;
            size_t dummy_in = 0;
            const uint8_t* dummy_next = NULL;
            int r = CompressStream(inst, 2, &dummy_in, &dummy_next, &avail_out2, (uint8_t**)&nxt_out2, &total_out);
            // Check if finished
            // Need to check if HasMoreOutput?
            // For simplicity, call until not has more output
            // We'll loop
            if(avail_out2>0){
                // Continue until finished
                // Check IsFinished via EncoderIsFinished ?
                typedef int (*IsFinished_t)(void*);
                IsFinished_t IsFinished = (IsFinished_t)dlsym(enc_handle, "BrotliEncoderIsFinished");
                if(IsFinished && IsFinished(inst)) break;
            }
            break;
        }
    }

    // Try more robust: use loop for FINISH
    size_t avail_in = in_len;
    const uint8_t* nxt_in = input;
    size_t avail_out = out_capacity;
    uint8_t* nxt_out = out_buf;
    size_t tot_out = 0;
    while(1){
        size_t in_before = avail_in;
        size_t out_before = avail_out;
        int op = (avail_in==0)?2:0;
        int r = CompressStream(inst, op, &avail_in, &nxt_in, &avail_out, &nxt_out, &tot_out);
        if(avail_in==0 && op==2){
            // Need to check if encoder finished
            typedef int (*IsFinished_t)(void*);
            IsFinished_t IsFinished = (IsFinished_t)dlsym(enc_handle, "BrotliEncoderIsFinished");
            if(IsFinished && IsFinished(inst)) break;
            if(avail_out==0){
                // Need bigger buffer
                out_capacity *=2;
                out_buf = realloc(out_buf, out_capacity);
                nxt_out = out_buf + tot_out;
                avail_out = out_capacity - tot_out;
                continue;
            }
        }
        if(avail_in==0 && avail_out!=out_before){
            // Produced some output, continue finishing
            continue;
        }
        if(avail_in==0){
            // No more input and no more output, break
            // Check HasMoreOutput
            typedef int (*HasMoreOutput_t)(void*);
            HasMoreOutput_t HasMore = (HasMoreOutput_t)dlsym(enc_handle, "BrotliEncoderHasMoreOutput");
            if(HasMore && HasMore(inst)){
                // need to take output
                typedef const uint8_t* (*TakeOutput_t)(void*, size_t*);
                TakeOutput_t TakeOutput = (TakeOutput_t)dlsym(enc_handle, "BrotliEncoderTakeOutput");
                if(TakeOutput){
                    size_t sz=0;
                    const uint8_t* data = TakeOutput(inst, &sz);
                    // This data is already in out_buf? Actually TakeOutput returns internal buffer, not our out_buf. So we need to copy.
                    // For simplicity, we used CompressStream which writes to out_buf directly, so we don't need TakeOutput.
                }
                continue;
            } else {
                break;
            }
        }
    }

    *out = out_buf;
    *out_len = tot_out;
    BrotliEncoderDestroyInstance(inst);
    return 0;
}

// Simplified compress using BrotliEncoderCompress directly (ignores large_window param but we set lgwin)
int brotli_compress_simple(const unsigned char* in, size_t in_len, unsigned char** out, size_t* out_len, int quality, int lgwin){
    size_t max_size = BrotliEncoderMaxCompressedSize(in_len);
    unsigned char* out_buf = malloc(max_size);
    size_t enc_size = max_size;
    int res = BrotliEncoderCompress(quality, lgwin, 0, in_len, in, &enc_size, out_buf);
    if(res){
        *out = out_buf;
        *out_len = enc_size;
        return 0;
    } else {
        free(out_buf);
        return -1;
    }
}

// Decompress
int brotli_decompress(const unsigned char* in, size_t in_len, unsigned char** out, size_t* out_len, int concatenated, int large_window){
    // Use streaming decoder
    void* state = BrotliDecoderCreateInstance(NULL,NULL,NULL);
    if(!state) return -1;
    if(concatenated){
        if(BrotliDecoderSetParameter) BrotliDecoderSetParameter(state, 3, 1); // CONCATENATED
    }
    if(large_window){
        if(BrotliDecoderSetParameter) BrotliDecoderSetParameter(state, 1, 1); // LARGE_WINDOW
    }
    size_t avail_in = in_len;
    const uint8_t* next_in = in;
    size_t out_capacity = in_len*4 + 1024;
    uint8_t* out_buf = malloc(out_capacity);
    size_t avail_out = out_capacity;
    uint8_t* next_out = out_buf;
    size_t total_out = 0;

    while(1){
        int res = BrotliDecoderDecompressStream(state, &avail_in, &next_in, &avail_out, &next_out, &total_out);
        if(res==0){ // error
            BrotliDecoderDestroyInstance(state);
            free(out_buf);
            return -1;
        }
        if(res==1){ // success
            if(avail_in==0) break;
            // If concatenated allowed, continue decoding next stream
            if(concatenated && avail_in>0){
                // Continue
                continue;
            } else {
                // If not concatenated and leftover input, it's corrupt
                if(avail_in>0){
                    BrotliDecoderDestroyInstance(state);
                    free(out_buf);
                    return -2; // leftover
                }
                break;
            }
        }
        if(res==2){ // needs more input, but we have no more
            break;
        }
        if(res==3){ // needs more output
            // Expand output buffer
            size_t old_cap = out_capacity;
            out_capacity *=2;
            out_buf = realloc(out_buf, out_capacity);
            next_out = out_buf + total_out;
            avail_out = out_capacity - total_out;
            continue;
        }
    }
    if(!BrotliDecoderIsFinished(state)){
        // Not finished, error
        BrotliDecoderDestroyInstance(state);
        free(out_buf);
        return -1;
    }
    *out = out_buf;
    *out_len = total_out;
    BrotliDecoderDestroyInstance(state);
    return 0;
}

// Helper to check file existence and type
int file_exists(const char* path){
    struct stat st;
    return stat(path,&st)==0;
}

int is_directory(const char* path){
    struct stat st;
    if(stat(path,&st)!=0) return 0;
    return S_ISDIR(st.st_mode);
}

// Base64 decode wrapper
int decode_comment(const char* b64_str, unsigned char** out, size_t* out_len){
    if(!b64_str || strlen(b64_str)==0) return -1;
    unsigned char* buf=NULL;
    size_t len=0;
    if(base64_decode(b64_str, &buf, &len)!=0){
        return -1;
    }
    if(len>80){
        free(buf);
        return -2; // too long, treat as invalid base64 per original (it says invalid base64-encoded comment for too long as well)
    }
    *out = buf;
    *out_len = len;
    return 0;
}

// Extract embedded comment from brotli file produced by original exe
// We implement generic extraction that tries to find comment at offset 1..4 with both varint formulas
unsigned char* extract_embedded_comment(const unsigned char* data, size_t data_len, size_t* comment_len_out){
    // Try to parse as per observed pattern: file starts with some byte, then varint (1 or 2 bytes), then comment (1..80), then rest
    // Varint formulas:
    // q11: varint = 11 + (C-1)*32
    // q0: varint = 1 + (C-1)*4
    // For lgwin 10..24, first byte varies but varint at offset 1 is 2-byte LE.

    // First try offset 1, 2-byte varint
    if(data_len>=4){
        for(int offset=1; offset<=4; offset++){
            if(data_len < offset+2+1) continue;
            int varint = data[offset] + (data[offset+1]<<8);
            // q11
            if(varint>=11 && (varint-11)%32==0){
                int C = (varint-11)/32+1;
                if(C>=1 && C<=80 && data_len >= offset+2+C){
                    // Check if after comment, the file has at least 1 byte (03 or something) and the file decodes? We can just return
                    // Additional heuristic: data[offset+2+C] should be 0x03 or something that starts with valid brotli? But for simplicity return
                    unsigned char* comment = malloc(C);
                    memcpy(comment, data+offset+2, C);
                    *comment_len_out = C;
                    return comment;
                }
            }
            // q0
            if(varint>=1 && (varint-1)%4==0){
                int C = (varint-1)/4+1;
                if(C>=1 && C<=80 && data_len >= offset+2+C){
                    unsigned char* comment = malloc(C);
                    memcpy(comment, data+offset+2, C);
                    *comment_len_out = C;
                    return comment;
                }
            }
        }
        // Try 1-byte varint at offset 1
        for(int offset=1; offset<=4; offset++){
            if(data_len < offset+1+1) continue;
            int varint = data[offset];
            if(varint>=11 && (varint-11)%32==0){
                int C = (varint-11)/32+1;
                if(C>=1 && C<=80 && data_len >= offset+1+C){
                    unsigned char* comment = malloc(C);
                    memcpy(comment, data+offset+1, C);
                    *comment_len_out = C;
                    return comment;
                }
            }
            if(varint>=1 && (varint-1)%4==0){
                int C = (varint-1)/4+1;
                if(C>=1 && C<=80 && data_len >= offset+1+C){
                    unsigned char* comment = malloc(C);
                    memcpy(comment, data+offset+1, C);
                    *comment_len_out = C;
                    return comment;
                }
            }
        }
    }
    return NULL;
}

