static int b64_index(char c){
    if(c>='A' && c<='Z') return c-'A';
    if(c>='a' && c<='z') return c-'a'+26;
    if(c>='0' && c<='9') return c-'0'+52;
    if(c=='+') return 62;
    if(c=='/') return 63;
    if(c=='=') return -2;
    return -1;
}

int base64_decode(const char* b64, unsigned char** out, size_t* out_len){
    size_t len = strlen(b64);
    if(len==0) return -1;
    for(size_t i=0;i<len;i++){
        if(b64_index(b64[i])==-1) return -1;
    }
    if(len%4!=0) return -1;
    size_t padding=0;
    if(len>=1 && b64[len-1]=='=') padding++;
    if(len>=2 && b64[len-2]=='=') padding++;
    size_t decoded_len = (len/4)*3 - padding;
    unsigned char* buf = malloc(decoded_len+1);
    size_t j=0;
    for(size_t i=0;i<len;i+=4){
        int a = b64_index(b64[i]);
        int b = b64_index(b64[i+1]);
        int c = b64_index(b64[i+2]);
        int d = b64_index(b64[i+3]);
        if(a==-1 || b==-1) { free(buf); return -1; }
        int c_val = (c==-2?0:c);
        int d_val = (d==-2?0:d);
        buf[j++] = (a<<2) | (b>>4);
        if(c!=-2) buf[j++] = ((b&0xF)<<4) | (c_val>>2);
        if(d!=-2) buf[j++] = ((c_val&0x3)<<6) | d_val;
    }
    *out = buf;
    *out_len = decoded_len;
    return 0;
}

