    if(out_cap<1024) out_cap=1024;
    uint8_t* out_buf = malloc(out_cap);
    size_t avail_out = out_cap;
    uint8_t* next_out = out_buf;
    size_t total_out = 0;

    while(1){
        int res = BrotliDecoderDecompressStream(state, &avail_in, &next_in, &avail_out, &next_out, &total_out);
        if(res==0){
            BrotliDecoderDestroyInstance(state);
            free(out_buf);
            return -1;
        }
        if(res==1){
            if(avail_in==0) break;
            if(concatenated && avail_in>0){
                continue;
            } else {
                // leftover input
                if(leftover) *leftover = avail_in;
                break;
            }
        }
        if(res==2){
            break;
        }
        if(res==3){
            size_t old = out_cap;
            out_cap*=2;
            out_buf = realloc(out_buf, out_cap);
            next_out = out_buf + total_out;
            avail_out = out_cap - total_out;
            continue;
        }
    }
    if(!BrotliDecoderIsFinished(state)){
        // If not finished, check if we have leftover and need more?
        // For our usage, if not finished, it's error
        int err = BrotliDecoderGetErrorCode ? BrotliDecoderGetErrorCode(state) : -1;
        // If leftover, we consider it success with leftover?
        // Actually for corrupt input, decoder will error
        if(leftover) *leftover = avail_in;
        // If not finished and total_out==0, it's error
        // We'll treat as error if not finished and avail_in==0?
        // For simplicity, if total_out>0 and avail_in>0 and not concatenated, it's leftover error but we still have output
        // We'll not treat as error here, let caller check leftover
    }
    BrotliDecoderDestroyInstance(state);
    *out = out_buf;
    *out_len = total_out;
    return 0;
}

unsigned char* extract_comment_original(const unsigned char* data, size_t data_len, size_t* c_len){
    if(data_len<4) return NULL;
    // Try offsets 1..4
    for(int offset=1; offset<=4 && offset+2 < (int)data_len; offset++){
        int varint = data[offset] + (data[offset+1]<<8);
        // q11
        if(varint>=11 && (varint-11)%32==0){
            int C = (varint-11)/32+1;
            if(C>=1 && C<=80 && data_len >= (size_t)(offset+2+C)){
                unsigned char* cmt = malloc(C);
                memcpy(cmt, data+offset+2, C);
                *c_len = C;
                return cmt;
            }
        }
        // q0
        if(varint>=1 && (varint-1)%4==0){
            int C = (varint-1)/4+1;
            if(C>=1 && C<=80 && data_len >= (size_t)(offset+2+C)){
                // Additional check: for q0, first byte should be something? We just return
                unsigned char* cmt = malloc(C);
                memcpy(cmt, data+offset+2, C);
                *c_len = C;
                return cmt;
            }
        }
    }
    // Try 1-byte varint at offset 1
    for(int offset=1; offset<=4 && offset+1 < (int)data_len; offset++){
        int varint = data[offset];
        if(varint>=11 && (varint-11)%32==0){
            int C = (varint-11)/32+1;
            if(C>=1 && C<=80 && data_len >= (size_t)(offset+1+C)){
                unsigned char* cmt = malloc(C);
                memcpy(cmt, data+offset+1, C);
                *c_len = C;
                return cmt;
            }
        }
        if(varint>=1 && (varint-1)%4==0){
            int C = (varint-1)/4+1;
            if(C>=1 && C<=80 && data_len >= (size_t)(offset+1+C)){
                unsigned char* cmt = malloc(C);
                memcpy(cmt, data+offset+1, C);
                *c_len = C;
                return cmt;
            }
        }
    }
    return NULL;
}

