                }
            }

            if(opts.command==2){
                // test mode
                if(opts.verbose){
                    fprintf(stderr, "Decompressed [%s]: %zu B -> %zu B in 0.00 sec\n", display_name, in_len, out_len);
                }
            } else {
                if(out_is_stdout){
                    fwrite(out_data,1,out_len,stdout);
                    if(opts.verbose){
                        fprintf(stderr, "Decompressed [%s]: %zu B -> %zu B in 0.00 sec\n", display_name, in_len, out_len);
                    }
                } else {
                    if(write_file(out_path, out_data, out_len)!=0){
                        fprintf(stderr, "failed to open output file [%s]: %s\n", out_path, strerror(errno));
                        overall_rc=1;
                    } else {
                        if(!opts.no_copy_stat && !is_stdin){
                            copy_stat(in_path, out_path);
                        }
                        if(opts.verbose){
                            fprintf(stderr, "Decompressed [%s]: %zu B -> %zu B in 0.00 sec\n", display_name, in_len, out_len);
                        }
                        if(opts.rm){
                            unlink(in_path);
                        }
                    }
                }
            }
            free(out_data);
        }

        free(in_data);
        if(out_path) free(out_path);
        if(dict_data) free(dict_data);
        if(embedded_c) free(embedded_c);
    }

    free_options(&opts);
    for(int j=0;j<input_count;j++) free(input_files[j]);
    free(input_files);
    return overall_rc;
}
