    BrotliEncoderSetParameter = (SetEncParam_t)dlsym(enc_handle, "BrotliEncoderSetParameter");
    BrotliEncoderDestroyInstance = (DestroyEncInst_t)dlsym(enc_handle, "BrotliEncoderDestroyInstance");
