    BrotliEncoderMaxCompressedSize = (MaxCompressedSize_t)dlsym(enc_handle, "BrotliEncoderMaxCompressedSize");
    BrotliDecoderCreateInstance = (CreateDecInst_t)dlsym(dec_handle, "BrotliDecoderCreateInstance");
    BrotliDecoderSetParameter = (SetDecParam_t)dlsym(dec_handle, "BrotliDecoderSetParameter");
