    BrotliDecoderDecompressStream = (DecStream_t)dlsym(dec_handle, "BrotliDecoderDecompressStream");
    BrotliDecoderIsFinished = (DecIsFinished_t)dlsym(dec_handle, "BrotliDecoderIsFinished");
    BrotliDecoderGetErrorCode = (DecGetError_t)dlsym(dec_handle, "BrotliDecoderGetErrorCode");
