            char* value=NULL;
            if(eq){ name=strndup(arg+2, eq-(arg+2)); value=eq+1; }
            else { name=strdup(arg+2); }

            if(strcmp(name,"help")==0){
                if(eq){ fprintf(stderr,"invalid parameter: [%s]\n", arg+2); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.help_version_first==0) opts.help_version_first=1;
                opts.help=1;
                free(name); i++; continue;
            }
            if(strcmp(name,"version")==0){
                if(eq){ fprintf(stderr,"invalid parameter: [%s]\n", arg+2); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.help_version_first==0) opts.help_version_first=2;
                opts.version=1;
                free(name); i++; continue;
            }
            if(strcmp(name,"stdout")==0){
                if(eq){ fprintf(stderr,"invalid parameter: [%s]\n", arg+2); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.stdout_flag){ fprintf(stderr,"write to standard output already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.output_set){ fprintf(stderr,"write to standard output already set (--output)\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                // Actually if output_set already, setting stdout should NOT error when output set first? According to earlier, output first then stdout -> no error.
                // But stdout first then output -> error.
                // So we need to check order: if output_set, then stdout should NOT error? Let's see: --output=out --stdout gave file exists error, not stdout error. So output first then stdout -> no stdout error, but file exists error? Actually we saw --output=out --stdout gave "failed to open output file [out]: File exists" when out exists, not stdout error. So when output_set first, stdout second is allowed (no error) but will be ignored? However for --stdout --output, it errors stdout already set.
                // So for stdout flag, if output_set already, we should NOT error, we should keep output and ignore stdout? But for --output=out -c, we saw rc0 and file created, no error. So output first then stdout -> no error.

                // However for --stdout alone duplicate, error.

                // So we need to implement: if stdout_flag already set, error. If output_set already set, do NOT error, just set stdout_flag? Or ignore? In test -o out --stdout gave file created, not stdout. So output wins.

                // Let's implement: if output_set, then set stdout_flag=0? Or keep output_set and not set stdout_flag.

                // For now, if output_set, we will not set stdout_flag and not error.

                if(opts.output_set){
                    // keep output, ignore stdout
                    free(name); i++; continue;
                }
                opts.stdout_flag=1;
                opts.stdout_set=1;
                free(name); i++; continue;
            }
            if(strcmp(name,"decompress")==0){
                if(eq){ fprintf(stderr,"invalid parameter: [%s]\n", arg+2); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.command!=0){ fprintf(stderr,"command already set when parsing %s\n", arg); printf("%s",help_text); err=1; free(name); goto cleanup; }
