                if(opts.command!=0){ fprintf(stderr,"command already set when parsing %s\n", arg); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.command=2;
                free(name); i++; continue;
            }
            if(strcmp(name,"verbose")==0){
                if(eq){ fprintf(stderr,"invalid parameter: [%s]\n", arg+2); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.verbose){ fprintf(stderr,"argument --verbose / -v already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.verbose=1;
                free(name); i++; continue;
            }
            if(strcmp(name,"concatenated")==0){
                if(eq){ fprintf(stderr,"invalid parameter: [%s]\n", arg+2); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.concatenated){ fprintf(stderr,"argument -K / --concatenated already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.concatenated=1;
                free(name); i++; continue;
            }
            if(strcmp(name,"best")==0){
                if(eq){ fprintf(stderr,"invalid parameter: [%s]\n", arg+2); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.quality_set){ fprintf(stderr,"quality already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.quality=11; opts.quality_set=1; opts.best=1;
                free(name); i++; continue;
            }

            int handled=0;
            if(strcmp(name,"output")==0){
                if(!eq){ fprintf(stderr,"must pass the parameter as --output=value\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(strlen(value)==0){ fprintf(stderr,"expected parameter for argument -o\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.stdout_flag){
                    // stdout first, output second -> error
                    fprintf(stderr,"write to standard output already set (--output)\n");
                    printf("%s",help_text); err=1; free(name); goto cleanup;
                }
                if(opts.output_file) free(opts.output_file);
                opts.output_file=strdup(value);
                opts.output_set=1;
                handled=1;
            } else if(strcmp(name,"quality")==0){
                if(!eq){ fprintf(stderr,"must pass the parameter as --quality=value\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.quality_set){ fprintf(stderr,"quality already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                int q;
                if(parse_int(value,&q)!=0 || q<0 || q>11){ fprintf(stderr,"error parsing quality value [%s]\n", value); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.quality=q; opts.quality_set=1; handled=1;
            } else if(strcmp(name,"lgwin")==0){
                if(!eq){ fprintf(stderr,"must pass the parameter as --lgwin=value\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.lgwin_set || opts.large_window_set){ fprintf(stderr,"lgwin parameter already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                int v;
                if(parse_int(value,&v)!=0){ fprintf(stderr,"error parsing lgwin value [%s]\n", value); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(v!=0 && v<10){ fprintf(stderr,"lgwin parameter (%d) smaller than the minimum (10)\n", v); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(v!=0 && v>24){ fprintf(stderr,"error parsing lgwin value [%s]\n", value); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.lgwin=v; opts.lgwin_set=1; handled=1;
            } else if(strcmp(name,"large_window")==0){
                if(!eq){ fprintf(stderr,"must pass the parameter as --large_window=value\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.lgwin_set || opts.large_window_set){ fprintf(stderr,"lgwin parameter already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                int v;
                if(parse_int(value,&v)!=0){ fprintf(stderr,"error parsing lgwin value [%s]\n", value); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(v!=0 && v<10){ fprintf(stderr,"lgwin parameter (%d) smaller than the minimum (10)\n", v); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(v!=0 && v>30){ fprintf(stderr,"error parsing lgwin value [%s]\n", value); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.large_window=v; opts.large_window_set=1; opts.lgwin=v; opts.lgwin_set=1; opts.lgwin_is_large=1; handled=1;
            } else if(strcmp(name,"comment")==0){
                if(!eq){ fprintf(stderr,"must pass the parameter as --comment=value\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.comment_set){ fprintf(stderr,"comment already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(strlen(value)==0){ fprintf(stderr,"expected parameter for argument -C\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                unsigned char* cmt=NULL; size_t clen=0;
                if(base64_decode(value,&cmt,&clen)!=0){ fprintf(stderr,"invalid base64-encoded comment\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.comment=cmt; opts.comment_len=clen; opts.comment_set=1; handled=1;
            } else if(strcmp(name,"dictionary")==0){
                if(!eq){ fprintf(stderr,"must pass the parameter as --dictionary=value\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.dict_set){ fprintf(stderr,"dictionary path already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                opts.dictionary=strdup(value); opts.dict_set=1; handled=1;
            } else if(strcmp(name,"suffix")==0){
                if(!eq){ fprintf(stderr,"must pass the parameter as --suffix=value\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                if(opts.suffix_set){ fprintf(stderr,"suffix already set\n"); printf("%s",help_text); err=1; free(name); goto cleanup; }
                free(opts.suffix); opts.suffix=strdup(value); opts.suffix_set=1; handled=1;
            }

            if(!handled){
                fprintf(stderr,"must pass the parameter as --%s=value\n", name);
                printf("%s",help_text);
                err=1; free(name); goto cleanup;
            }
            free(name);
            i++; continue;
        }

        // short
        char* p=arg+1;
        int param_handled=0;
        while(*p){
            char c=*p;
            if(c>='0' && c<='9'){
                if(opts.quality_set){ fprintf(stderr,"quality already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.quality=c-'0'; opts.quality_set=1;
                p++; continue;
            }
            if(c=='c'){
                if(opts.stdout_flag){ fprintf(stderr,"write to standard output already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                if(opts.output_set){
                    // output first, stdout second -> no error, keep output, ignore stdout? Actually for short, -o out -c gave rc0 and file, so output wins, no stdout.
                    // So we should NOT set stdout_flag, keep output
                    p++; continue;
                }
                opts.stdout_flag=1;
                opts.stdout_set=1;
                p++; continue;
            }
            if(c=='d'){
                if(opts.command!=0){ fprintf(stderr,"command already set when parsing -%c\n", c); printf("%s",help_text); err=1; goto cleanup; }
                opts.command=1;
                p++; continue;
            }
            if(c=='f'){
                if(opts.force){ fprintf(stderr,"force output overwrite already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.force=1;
                p++; continue;
            }
            if(c=='h'){
                if(opts.help_version_first==0) opts.help_version_first=1;
                opts.help=1;
                p++; continue;
            }
            if(c=='j'){
                if(opts.rm_set || opts.keep_set){ fprintf(stderr,"argument --rm / -j or --keep / -k already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.rm=1; opts.keep=0; opts.rm_set=1;
                p++; continue;
            }
            if(c=='s'){
                if(opts.squash){ fprintf(stderr,"argument --squash / -s already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.squash=1;
                p++; continue;
            }
            if(c=='k'){
                if(opts.rm_set || opts.keep_set){ fprintf(stderr,"argument --rm / -j or --keep / -k already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.keep=1; opts.keep_set=1;
                p++; continue;
            }
            if(c=='n'){
                if(opts.no_copy_stat){ fprintf(stderr,"argument --no-copy-stat / -n already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.no_copy_stat=1;
                p++; continue;
            }
            if(c=='t'){
                if(opts.command!=0){ fprintf(stderr,"command already set when parsing -%c\n", c); printf("%s",help_text); err=1; goto cleanup; }
                opts.command=2;
                p++; continue;
            }
            if(c=='v'){
                if(opts.verbose){ fprintf(stderr,"argument --verbose / -v already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.verbose=1;
                p++; continue;
            }
            if(c=='K'){
                if(opts.concatenated){ fprintf(stderr,"argument -K / --concatenated already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.concatenated=1;
                p++; continue;
            }
            if(c=='Z'){
                if(opts.quality_set){ fprintf(stderr,"quality already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                opts.quality=11; opts.quality_set=1; opts.best=1;
                p++; continue;
            }
            if(c=='V'){
                if(opts.help_version_first==0) opts.help_version_first=2;
                opts.version=1;
                p++; continue;
            }
            if(c=='o' || c=='q' || c=='w' || c=='C' || c=='D' || c=='S'){
                if(*(p+1)!='\0'){ fprintf(stderr,"expected parameter for argument -%c\n", c); printf("%s",help_text); err=1; goto cleanup; }
                if(i+1>=argc){ fprintf(stderr,"expected parameter for argument -%c\n", c); printf("%s",help_text); err=1; goto cleanup; }
                char* val=argv[i+1];
                if(c=='o'){
                    if(opts.stdout_flag){
                        fprintf(stderr,"write to standard output already set (-o)\n");
                        printf("%s",help_text); err=1; goto cleanup;
                    }
                    if(opts.output_file) free(opts.output_file);
                    opts.output_file=strdup(val);
                    opts.output_set=1;
                } else if(c=='q'){
                    if(opts.quality_set){ fprintf(stderr,"quality already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                    int q;
                    if(parse_int(val,&q)!=0 || q<0 || q>11){ fprintf(stderr,"error parsing quality value [%s]\n", val); printf("%s",help_text); err=1; goto cleanup; }
                    opts.quality=q; opts.quality_set=1;
                } else if(c=='w'){
                    if(opts.lgwin_set || opts.large_window_set){ fprintf(stderr,"lgwin parameter already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                    int v;
                    if(parse_int(val,&v)!=0){ fprintf(stderr,"error parsing lgwin value [%s]\n", val); printf("%s",help_text); err=1; goto cleanup; }
                    if(v!=0 && v<10){ fprintf(stderr,"lgwin parameter (%d) smaller than the minimum (10)\n", v); printf("%s",help_text); err=1; goto cleanup; }
                    if(v!=0 && v>24){ fprintf(stderr,"error parsing lgwin value [%s]\n", val); printf("%s",help_text); err=1; goto cleanup; }
                    opts.lgwin=v; opts.lgwin_set=1;
                } else if(c=='C'){
                    if(opts.comment_set){ fprintf(stderr,"comment already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                    if(strlen(val)==0){ fprintf(stderr,"expected parameter for argument -C\n"); printf("%s",help_text); err=1; goto cleanup; }
                    unsigned char* cmt=NULL; size_t clen=0;
                    if(base64_decode(val,&cmt,&clen)!=0){ fprintf(stderr,"invalid base64-encoded comment\n"); printf("%s",help_text); err=1; goto cleanup; }
                    opts.comment=cmt; opts.comment_len=clen; opts.comment_set=1;
                } else if(c=='D'){
                    if(opts.dict_set){ fprintf(stderr,"dictionary path already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                    opts.dictionary=strdup(val); opts.dict_set=1;
                } else if(c=='S'){
                    if(opts.suffix_set){ fprintf(stderr,"suffix already set\n"); printf("%s",help_text); err=1; goto cleanup; }
                    free(opts.suffix); opts.suffix=strdup(val); opts.suffix_set=1;
                }
                param_handled=1;
                i+=2;
                break;
            } else {
                // invalid
                // Check if it's an unknown long-like? Actually short invalid
                char tmp[2]={c,0};
                // For invalid short, original prints "invalid parameter: [X]" ? Let's test: -x invalid? We haven't tested invalid short.
                // We'll print invalid parameter
                fprintf(stderr,"invalid parameter: [%c]\n", c);
                printf("%s",help_text);
                err=1; goto cleanup;
            }
        }
        if(!param_handled) i++;
    }

cleanup:
    if(opts.help || opts.version){
        if(opts.help_version_first==1 || (opts.help && !opts.version)){
            fprintf(stderr, "%s", help_text);
        } else if(opts.help_version_first==2 || opts.version){
            printf("brotli 1.2.0\n");
        } else {
            if(opts.help) fprintf(stderr, "%s", help_text);
            else printf("brotli 1.2.0\n");
        }
        free_opts(&opts);
        for(int j=0;j<input_count;j++) free(input_files[j]);
        free(input_files);
        return 0;
    }
    if(err){
        free_opts(&opts);
        for(int j=0;j<input_count;j++) free(input_files[j]);
        free(input_files);
        return 1;
    }

    // Check stdout with multiple files
    if(opts.stdout_flag && input_count>1){
        printf("%s",help_text);
        free_opts(&opts);
        for(int j=0;j<input_count;j++) free(input_files[j]);
        free(input_files);
        return 1;
    }
    // Check -c -t etc? -t with -c should fail with help (no message)
    if(opts.command==2 && opts.stdout_flag){
        printf("%s",help_text);
        free_opts(&opts);
        for(int j=0;j<input_count;j++) free(input_files[j]);
        free(input_files);
        return 1;
    }
    // -t with -o?
    if(opts.command==2 && opts.output_set){
        printf("%s",help_text);
        free_opts(&opts);
        for(int j=0;j<input_count;j++) free(input_files[j]);
        free(input_files);
        return 1;
    }

    // Main processing
    int overall_rc=0;
    if(input_count==0){
        // stdin
        size_t cap=1024*1024;
        unsigned char* in_data=malloc(cap);
        size_t total=0;
        size_t n;
        while((n=fread(in_data+total,1,cap-total,stdin))>0){
            total+=n;
            if(total==cap){ cap*=2; in_data=realloc(in_data,cap); }
        }
        size_t in_len=total;

        if(opts.command==0){
            unsigned char* out_data=NULL;
            size_t out_len=0;
            int lg=opts.lgwin;
            if(lg==0) lg=24;
            if(opts.large_window_set && opts.large_window!=0) lg=opts.large_window;
            if(opts.comment_set){
                // For stdin, produce file with comment using default first byte 6f if lgwin 24 else 21
                int C=opts.comment_len;
                if(in_len<=10){
                    int first_byte=0x6f;
                    int varint_c=1+(C-1)*4;
                    if(lg==10) { first_byte=0x21; varint_c=11+(C-1)*32; }
                    int varint_content = (in_len>0)? (in_len-1)*8 : 0;
                    if(in_len==0){
                        size_t need=1+2+C+1;
                        out_data=malloc(need);
                        out_data[0]=first_byte;
                        out_data[1]=varint_c&0xFF;
                        out_data[2]=(varint_c>>8)&0xFF;
                        memcpy(out_data+3, opts.comment, C);
                        out_data[3+C]=0x03;
                        out_len=need;
                    } else {
                        size_t need=1+2+C+2+1+in_len+1;
                        out_data=malloc(need);
                        out_data[0]=first_byte;
                        out_data[1]=varint_c&0xFF;
                        out_data[2]=(varint_c>>8)&0xFF;
                        memcpy(out_data+3, opts.comment, C);
                        out_data[3+C]=varint_content&0xFF;
                        out_data[4+C]=(varint_content>>8)&0xFF;
                        out_data[5+C]=0x08;
                        memcpy(out_data+6+C, in_data, in_len);
                        out_data[6+C+in_len]=0x03;
                        out_len=need;
                    }
                } else {
                    // concatenated
                    int first_byte=0x6f;
                    int varint_c=1+(C-1)*4;
                    if(lg==10){ first_byte=0x21; varint_c=11+(C-1)*32; }
                    size_t empty_len=1+2+C+1;
                    unsigned char* empty_buf=malloc(empty_len);
                    empty_buf[0]=first_byte;
                    empty_buf[1]=varint_c&0xFF;
                    empty_buf[2]=(varint_c>>8)&0xFF;
                    memcpy(empty_buf+3, opts.comment, C);
                    empty_buf[3+C]=0x03;
                    unsigned char* comp=NULL; size_t comp_len=0;
                    brotli_compress_simple(in_data,in_len,&comp,&comp_len,opts.quality,lg);
                    out_len=empty_len+comp_len;
                    out_data=malloc(out_len);
                    memcpy(out_data,empty_buf,empty_len);
                    memcpy(out_data+empty_len,comp,comp_len);
                    free(empty_buf); free(comp);
                }
            } else {
                brotli_compress_simple(in_data,in_len,&out_data,&out_len,opts.quality,lg);
            }
            if(opts.squash && out_len>in_len){
                if(opts.verbose){
                    fprintf(stderr,"Compressed [con]: %zu B -> %zu B in 0.00 sec\n",in_len,out_len);
                    fprintf(stderr,"Output is larger than input\n");
                }
            } else {
                fwrite(out_data,1,out_len,stdout);
                if(opts.verbose){
                    fprintf(stderr,"Compressed [con]: %zu B -> %zu B in 0.00 sec\n",in_len,out_len);
                }
            }
            free(out_data);
        } else {
            // decompress
            size_t c_len=0;
            unsigned char* cmt=extract_comment(in_data,in_len,&c_len);
            if(opts.comment_set){
                if(cmt){
                    if(c_len!=opts.comment_len || memcmp(cmt,opts.comment,c_len)!=0){
                        fprintf(stderr,"corrupt input [con]\n");
                        if(opts.verbose) fprintf(stderr,"reason: comment mismatch\n");
                        free(cmt); free(in_data); free_opts(&opts); for(int j=0;j<input_count;j++) free(input_files[j]); free(input_files); return 1;
                    }
                    free(cmt);
                } else {
                    fprintf(stderr,"corrupt input [con]\n");
                    if(opts.verbose) fprintf(stderr,"reason: comment mismatch\n");
                }
            } else {
                if(cmt) free(cmt);
            }
            unsigned char* out_data=NULL;
            size_t out_len=0;
            size_t leftover=0;
            int res=brotli_decompress_stream(in_data,in_len,&out_data,&out_len,opts.concatenated,opts.large_window_set,&leftover);
            if(res!=0){
                fprintf(stderr,"corrupt input [con]\n");
                free(in_data); free_opts(&opts); for(int j=0;j<input_count;j++) free(input_files[j]); free(input_files); return 1;
            }
            if(leftover>0 && !opts.concatenated){
                fprintf(stderr,"corrupt input [con]\n");
                if(out_data) free(out_data);
                free(in_data);
                free_opts(&opts);
                for(int j=0;j<input_count;j++) free(input_files[j]);
                free(input_files);
                return 1;
            }
            if(opts.command==2){
                if(opts.verbose) fprintf(stderr,"Decompressed [con]: %zu B -> %zu B in 0.00 sec\n",in_len,out_len);
            } else {
                fwrite(out_data,1,out_len,stdout);
                if(opts.verbose) fprintf(stderr,"Decompressed [con]: %zu B -> %zu B in 0.00 sec\n",in_len,out_len);
            }
            free(out_data);
        }
        free(in_data);
        free_opts(&opts);
        for(int j=0;j<input_count;j++) free(input_files[j]);
        free(input_files);
        return 0;
    }

    for(int idx=0; idx<input_count; idx++){
        char* in_path=input_files[idx];
        int is_stdin = (strcmp(in_path,"-")==0);
        const char* disp = is_stdin ? "con" : in_path;
        unsigned char* in_data=NULL;
        size_t in_len=0;
        if(is_stdin){
            size_t cap=1024*1024;
            in_data=malloc(cap);
            size_t total=0;
            size_t n;
            while((n=fread(in_data+total,1,cap-total,stdin))>0){
                total+=n;
                if(total==cap){ cap*=2; in_data=realloc(in_data,cap); }
            }
            in_len=total;
        } else {
            if(!file_exists(in_path)){
                fprintf(stderr,"failed to open input file [%s]: No such file or directory\n",in_path);
                overall_rc=1;
                continue;
            }
            if(is_dir(in_path)){
                fprintf(stderr,"failed to open input file [%s]: Is a directory\n",in_path);
                overall_rc=1;
                continue;
            }
            if(read_file(in_path,&in_data,&in_len)!=0){
                fprintf(stderr,"failed to open input file [%s]: No such file or directory\n",in_path);
                overall_rc=1;
                continue;
            }
        }

        char* out_path=NULL;
        int out_stdout=0;
        if(opts.output_set){
            out_path=strdup(opts.output_file);
        } else if(opts.stdout_flag || opts.command==2){
            out_stdout=1;
        } else {
            if(opts.command==0){
                size_t len=strlen(in_path)+strlen(opts.suffix)+1;
                out_path=malloc(len);
                snprintf(out_path,len,"%s%s",in_path,opts.suffix);
            } else {
                size_t plen=strlen(in_path);
                size_t slen=strlen(opts.suffix);
                if(plen<slen || strcmp(in_path+plen-slen, opts.suffix)!=0){
                    fprintf(stderr,"input file [%s] suffix mismatch\n",in_path);
                    overall_rc=1;
                    free(in_data);
                    continue;
                }
                out_path=strndup(in_path, plen-slen);
            }
        }

        if(!out_stdout && opts.command!=2){
            if(file_exists(out_path) && !opts.force){
                fprintf(stderr,"failed to open output file [%s]: File exists\n",out_path);
                overall_rc=1;
                free(in_data);
                free(out_path);
                continue;
            }
        }

        unsigned char* dict_data=NULL;
        size_t dict_len=0;
        if(opts.dict_set){
            if(read_file(opts.dictionary,&dict_data,&dict_len)!=0){
                fprintf(stderr,"failed to open dictionary file [%s]: No such file or directory\n",opts.dictionary);
                overall_rc=1;
                free(in_data);
                if(out_path) free(out_path);
                continue;
            }
        }

        if(opts.command==0){
            unsigned char* out_data=NULL;
            size_t out_len=0;
            int lg=opts.lgwin;
            if(lg==0) lg=24;
            if(opts.large_window_set && opts.large_window!=0) lg=opts.large_window;

            if(opts.comment_set){
                int C=opts.comment_len;
                int L=in_len;
                if(L<=10){
                    int first_byte=0x6f;
                    int varint_c=1+(C-1)*4;
                    if(lg==10){ first_byte=0x21; varint_c=11+(C-1)*32; }
                    else if(lg==20){ first_byte=0x67; varint_c=1+(C-1)*4; }
                    else if(lg<=15){ first_byte=0x21 + (lg-10)*0x10; varint_c=11+(C-1)*32; }
                    else { first_byte=0x6f; varint_c=1+(C-1)*4; }
                    if(L==0){
                        size_t need=1+2+C+1;
                        out_data=malloc(need);
                        out_data[0]=first_byte;
                        out_data[1]=varint_c&0xFF;
                        out_data[2]=(varint_c>>8)&0xFF;
                        memcpy(out_data+3, opts.comment, C);
                        out_data[3+C]=0x03;
                        out_len=need;
                    } else {
                        int varint_content=(L-1)*8;
                        size_t need=1+2+C+2+1+L+1;
                        out_data=malloc(need);
                        out_data[0]=first_byte;
                        out_data[1]=varint_c&0xFF;
                        out_data[2]=(varint_c>>8)&0xFF;
                        memcpy(out_data+3, opts.comment, C);
                        out_data[3+C]=varint_content&0xFF;
                        out_data[4+C]=(varint_content>>8)&0xFF;
                        out_data[5+C]=0x08;
                        memcpy(out_data+6+C, in_data, L);
                        out_data[6+C+L]=0x03;
                        out_len=need;
                    }
                } else {
                    int first_byte=0x6f;
                    int varint_c=1+(C-1)*4;
                    if(lg==10){ first_byte=0x21; varint_c=11+(C-1)*32; }
                    size_t empty_len=1+2+C+1;
                    unsigned char* empty_buf=malloc(empty_len);
                    empty_buf[0]=first_byte;
                    empty_buf[1]=varint_c&0xFF;
                    empty_buf[2]=(varint_c>>8)&0xFF;
                    memcpy(empty_buf+3, opts.comment, C);
                    empty_buf[3+C]=0x03;
                    unsigned char* comp=NULL; size_t comp_len=0;
                    brotli_compress_simple(in_data,in_len,&comp,&comp_len,opts.quality,lg);
                    out_len=empty_len+comp_len;
                    out_data=malloc(out_len);
                    memcpy(out_data,empty_buf,empty_len);
                    memcpy(out_data+empty_len,comp,comp_len);
                    free(empty_buf); free(comp);
                }
            } else {
                if(brotli_compress_simple(in_data,in_len,&out_data,&out_len,opts.quality,lg)!=0){
                    fprintf(stderr,"failed to compress [%s]\n",disp);
                    overall_rc=1;
                    free(in_data);
                    if(out_path) free(out_path);
                    if(dict_data) free(dict_data);
                    continue;
                }
            }

            if(opts.squash && out_len>in_len){
                if(opts.verbose){
                    fprintf(stderr,"Compressed [%s]: %zu B -> %zu B in 0.00 sec\n",disp,in_len,out_len);
                    fprintf(stderr,"Output is larger than input\n");
                }
                if(out_path && file_exists(out_path)) unlink(out_path);
                free(out_data);
            } else {
                if(out_stdout){
                    fwrite(out_data,1,out_len,stdout);
                    if(opts.verbose) fprintf(stderr,"Compressed [%s]: %zu B -> %zu B in 0.00 sec\n",disp,in_len,out_len);
                } else {
                    if(write_file(out_path,out_data,out_len)!=0){
                        fprintf(stderr,"failed to open output file [%s]: %s\n",out_path,strerror(errno));
                        overall_rc=1;
                    } else {
                        if(!opts.no_copy_stat && !is_stdin) copy_stat(in_path,out_path);
                        if(opts.verbose) fprintf(stderr,"Compressed [%s]: %zu B -> %zu B in 0.00 sec\n",disp,in_len,out_len);
                        if(opts.rm) unlink(in_path);
                    }
                }
                free(out_data);
            }

        } else {
            // decompress / test
            size_t emb_len=0;
            unsigned char* emb=extract_comment(in_data,in_len,&emb_len);
            int mismatch=0;
            if(opts.comment_set){
                if(emb){
                    if(emb_len!=opts.comment_len || memcmp(emb,opts.comment,emb_len)!=0) mismatch=1;
                }
            }

            if(mismatch){
                fprintf(stderr,"corrupt input [%s]\n",disp);
                if(opts.verbose) fprintf(stderr,"reason: comment mismatch\n");
                overall_rc=1;
                free(in_data);
                if(out_path) free(out_path);
                if(dict_data) free(dict_data);
                if(emb) free(emb);
                continue;
            }

            unsigned char* out_data=NULL;
            size_t out_len=0;
            size_t leftover=0;
            int dec_res=brotli_decompress_stream(in_data,in_len,&out_data,&out_len,opts.concatenated,opts.large_window_set,&leftover);

            if(dec_res!=0){
                fprintf(stderr,"corrupt input [%s]\n",disp);
                overall_rc=1;
                free(in_data);
                if(out_path) free(out_path);
                if(dict_data) free(dict_data);
                if(emb) free(emb);
                if(out_data) free(out_data);
                continue;
            }
            if(leftover>0 && !opts.concatenated){
                // For original, if leftover>0 and not concatenated, it outputs first stream and reports corrupt
                // We'll do similar: output out_data if any, report corrupt, rc=1
                if(out_data && out_len>0 && opts.command!=2){
                    if(out_stdout){
                        fwrite(out_data,1,out_len,stdout);
                    } else if(out_path){
                        if(!file_exists(out_path) || opts.force){
                            write_file(out_path,out_data,out_len);
                            if(!opts.no_copy_stat && !is_stdin) copy_stat(in_path,out_path);
                        }
                    }
                }
                fprintf(stderr,"corrupt input [%s]\n",disp);
                overall_rc=1;
                free(out_data);
                free(in_data);
                if(out_path) free(out_path);
                if(dict_data) free(dict_data);
                if(emb) free(emb);
                continue;
            }

            if(opts.comment_set && !emb){
                fprintf(stderr,"corrupt input [%s]\n",disp);
                if(opts.verbose) fprintf(stderr,"reason: comment mismatch\n");
            }

            if(opts.squash && !out_stdout && opts.command!=2){
                if(out_len>in_len){
                    if(opts.verbose){
                        fprintf(stderr,"Decompressed [%s]: %zu B -> %zu B in 0.00 sec\n",disp,in_len,out_len);
                        fprintf(stderr,"Output is larger than input\n");
                    }
                    if(out_path && file_exists(out_path)) unlink(out_path);
                    free(out_data);
                    free(in_data);
                    if(out_path) free(out_path);
                    if(dict_data) free(dict_data);
                    if(emb) free(emb);
                    continue;
                }
            }

            if(opts.command==2){
                if(opts.verbose) fprintf(stderr,"Decompressed [%s]: %zu B -> %zu B in 0.00 sec\n",disp,in_len,out_len);
            } else {
                if(out_stdout){
                    fwrite(out_data,1,out_len,stdout);
                    if(opts.verbose) fprintf(stderr,"Decompressed [%s]: %zu B -> %zu B in 0.00 sec\n",disp,in_len,out_len);
                } else {
                    if(write_file(out_path,out_data,out_len)!=0){
                        fprintf(stderr,"failed to open output file [%s]: %s\n",out_path,strerror(errno));
                        overall_rc=1;
                    } else {
                        if(!opts.no_copy_stat && !is_stdin) copy_stat(in_path,out_path);
                        if(opts.verbose) fprintf(stderr,"Decompressed [%s]: %zu B -> %zu B in 0.00 sec\n",disp,in_len,out_len);
                        if(opts.rm) unlink(in_path);
                    }
                }
            }
            free(out_data);
            if(emb) free(emb);
        }

        free(in_data);
        if(out_path) free(out_path);
        if(dict_data) free(dict_data);
    }

    free_opts(&opts);
    for(int j=0;j<input_count;j++) free(input_files[j]);
    free(input_files);
    return overall_rc;
}
