int parse_int(const char* s, int* out){
    char* end;
    long v=strtol(s,&end,10);
    if(end==s || *end!='\0') return -1;
    *out=(int)v;
    return 0;
}

static int b64_idx(char c){
    if(c>='A'&&c<='Z') return c-'A';
    if(c>='a'&&c<='z') return c-'a'+26;
    if(c>='0'&&c<='9') return c-'0'+52;
    if(c=='+') return 62;
    if(c=='/') return 63;
    if(c=='=') return -2;
    return -1;
}

int base64_decode(const char* b64, unsigned char** out, size_t* out_len){
    size_t len=strlen(b64);
    if(len==0) return -1;
    for(size_t i=0;i<len;i++) if(b64_idx(b64[i])==-1) return -1;
    if(len%4!=0) return -1;
    size_t pad=0;
    if(len>=1 && b64[len-1]=='=') pad++;
    if(len>=2 && b64[len-2]=='=') pad++;
    size_t dlen=(len/4)*3 - pad;
    if(dlen>80) { return -1; } // original says invalid for >80 as well (we treat as invalid base64)
    unsigned char* buf=malloc(dlen+1);
    size_t j=0;
    for(size_t i=0;i<len;i+=4){
        int a=b64_idx(b64[i]);
        int b=b64_idx(b64[i+1]);
        int c=b64_idx(b64[i+2]);
        int d=b64_idx(b64[i+3]);
        if(a==-1||b==-1){ free(buf); return -1; }
        int cv=c==-2?0:c;
        int dv=d==-2?0:d;
        buf[j++]=(a<<2)|(b>>4);
        if(c!=-2) buf[j++]=((b&0xF)<<4)|(cv>>2);
        if(d!=-2) buf[j++]=((cv&0x3)<<6)|dv;
    }
    *out=buf;
    *out_len=dlen;
    return 0;
}

int file_exists(const char* p){
    struct stat st;
    return stat(p,&st)==0;
}
int is_dir(const char* p){
    struct stat st;
    if(stat(p,&st)!=0) return 0;
    return S_ISDIR(st.st_mode);
}
int read_file(const char* path, unsigned char** data, size_t* len){
    FILE* f=fopen(path,"rb");
    if(!f) return -1;
    fseek(f,0,SEEK_END);
    long sz=ftell(f);
    fseek(f,0,SEEK_SET);
    if(sz<0) sz=0;
    unsigned char* buf=malloc(sz+1);
    size_t r=fread(buf,1,sz,f);
    fclose(f);
    *data=buf; *len=r;
    return 0;
}
int write_file(const char* path, unsigned char* data, size_t len){
    FILE* f=fopen(path,"wb");
    if(!f) return -1;
    fwrite(data,1,len,f);
    fclose(f);
    return 0;
}
int copy_stat(const char* src, const char* dst){
    struct stat st;
    if(stat(src,&st)!=0) return -1;
    chmod(dst, st.st_mode & 0777);
    struct utimbuf ub;
    ub.actime=st.st_atime;
    ub.modtime=st.st_mtime;
    utime(dst,&ub);
    return 0;
}

int brotli_compress_simple(const unsigned char* in, size_t in_len, unsigned char** out, size_t* out_len, int quality, int lgwin){
    size_t max_size=BrotliEncoderMaxCompressedSize(in_len);
    unsigned char* out_buf=malloc(max_size+16);
    size_t enc_size=max_size;
    int res=BrotliEncoderCompress(quality, lgwin, 0, in_len, in, &enc_size, out_buf);
    if(res){ *out=out_buf; *out_len=enc_size; return 0; }
    free(out_buf);
    return -1;
}

int brotli_decompress_stream(const unsigned char* in, size_t in_len, unsigned char** out, size_t* out_len, int concat, int large_win, size_t* leftover){
    void* state=BrotliDecoderCreateInstance(NULL,NULL,NULL);
    if(!state) return -1;
    if(concat && BrotliDecoderSetParameter) BrotliDecoderSetParameter(state,3,1);
    if(large_win && BrotliDecoderSetParameter) BrotliDecoderSetParameter(state,1,1);
    size_t avail_in=in_len;
    const uint8_t* next_in=in;
    size_t out_cap=in_len*4+1024;
    if(out_cap<1024) out_cap=1024;
    uint8_t* out_buf=malloc(out_cap);
    size_t avail_out=out_cap;
    uint8_t* next_out=out_buf;
    size_t total_out=0;
    while(1){
        int res=BrotliDecoderDecompressStream(state,&avail_in,&next_in,&avail_out,&next_out,&total_out);
        if(res==0){ BrotliDecoderDestroyInstance(state); free(out_buf); return -1; }
        if(res==1){
            if(avail_in==0) break;
            if(concat && avail_in>0) continue;
            else { if(leftover) *leftover=avail_in; break; }
        }
        if(res==2) break;
        if(res==3){
            size_t old=out_cap;
            out_cap*=2;
            out_buf=realloc(out_buf,out_cap);
            next_out=out_buf+total_out;
            avail_out=out_cap-total_out;
            continue;
        }
    }
    BrotliDecoderDestroyInstance(state);
    *out=out_buf;
    *out_len=total_out;
    if(leftover && avail_in>0) *leftover=avail_in;
    else if(leftover) *leftover=0;
    return 0;
}

unsigned char* extract_comment(const unsigned char* data, size_t len, size_t* clen){
    if(len<4) return NULL;
    for(int off=1; off<=4 && off+2 < (int)len; off++){
        int varint = data[off] + (data[off+1]<<8);
        if(varint>=11 && (varint-11)%32==0){
            int C=(varint-11)/32+1;
            if(C>=1 && C<=80 && len>= (size_t)(off+2+C)){
                unsigned char* c=malloc(C);
                memcpy(c,data+off+2,C);
                *clen=C;
                return c;
            }
        }
        if(varint>=1 && (varint-1)%4==0){
            int C=(varint-1)/4+1;
            if(C>=1 && C<=80 && len>= (size_t)(off+2+C)){
                unsigned char* c=malloc(C);
                memcpy(c,data+off+2,C);
                *clen=C;
                return c;
            }
        }
    }
    // also try offset 2 for lgwin16 case where header 2 bytes: ac 00 68 69...
    // For lgwin16 empty hi: ac 00 68 69 03, comment at offset 2
    if(len>=4){
        // try offset 2
        for(int off=2; off<=4 && off+2 < (int)len; off++){
            int varint = data[off-1] + (data[off]<<8); // not accurate, try single byte?
            // Actually for lg16 ac 00 68 69, varint at offset 0 = ac 00 =172, which is 43*4, comment at offset2
            // So we can try to find comment by scanning for first occurrence where after header, the file ends with 03 and rest decodes? Simpler: just search for comment that is at offset 2 and header 2 bytes
        }
    }
    // Fallback: try to find comment as substring at offset 2 or 3 that matches known pattern: for empty file, file is [header][comment][03]
    // For empty file, last byte is 03, and file length = header_len + C +1
    // header_len is 2 or 3. So we can try header_len 2 and 3.

    // Try header_len 2: file = [b0][b1][comment][03]
    if(len>=4 && data[len-1]==0x03){
        for(int h=1; h<=4; h++){
            if(len < h+1+1) continue;
            int C = len - h -1;
            if(C<1 || C>80) continue;
            // Check if varint at offset 1 matches C
            // For h=2, varint at offset1? Actually header is h bytes, varint is inside header?
            // For simplicity, if file ends with 03 and contains comment, we can extract middle
            // For empty file, middle is comment
            // So if file decodes to empty via brotli, then middle is comment
            // Let's try decompress to see if it decodes to empty
            unsigned char* out=NULL; size_t out_len=0; size_t leftover=0;
            if(brotli_decompress_stream(data,len,&out,&out_len,0,0,&leftover)==0 && out_len==0 && leftover==0){
                // It's empty file, so comment is middle part
                if(h==1){
                    // file = [b0][comment][03] ? For lg16 C1: 2c 00 62 03 -> h=2? Actually b0=2c,b1=00,comment 62,03 => h=2
                    // So for len 4, h=2, C=1
                    // For len 6, ac 00 68 69 03? Wait ac 00 68 69 03 is 5 bytes: h=2, C=2
                }
                // For empty, C = len - h -1
                // So we can attempt to extract
                if(C>=1 && C<=80){
                    unsigned char* c=malloc(C);
                    memcpy(c, data+h, C);
                    *clen=C;
                    free(out);
                    return c;
                }
            }
            if(out) free(out);
        }
    }

    return NULL;
}

